def count_undoubtedly_lucky(n):
    # Helper function to count numbers in range [0, k] that are undoubtedly lucky with digits x and y
    def count_numbers(k, x, y):
        if k == 0:
            return 1
        count = 0
        for i in range(10):
            if i == x or i == y:
                count += count_numbers(k // 10, x, y)
            else:
                count += count_numbers(k // 10, x, y)
        return count

    # Convert n to string to easily iterate over each digit
    n_str = str(n)
    length = len(n_str)

    # Initialize the answer with the number of numbers ending in 0, 1, 2, ..., 9
    answer = length

    # Iterate over each digit position
    for i in range(1, length):
        # If the current digit is 0, 1, 2, ..., 9, the number is undoubtedly lucky
        if n_str[i] in '0123456789':
            answer += 1
        else:
            # If the current digit is not lucky, subtract the count of numbers that end with this digit
            if n_str[i] == '0':
                answer -= count_numbers(int('1' * length), '0', '0')
            elif n_str[i] == '1':
                answer -= count_numbers(int('1' * length), '1', '1')
            elif n_str[i] == '2':
                answer -= count_numbers(int('1' * length), '2', '2')
            elif n_str[i] == '3':
                answer -= count_numbers(int('1' * length), '3', '3')
            elif n_str[i] == '4':
                answer -= count_numbers(int('1' * length), '4', '4')
            elif n_str[i] == '5':
                answer -= count_numbers(int('1' * length), '5', '5')
            elif n_str[i] == '6':
                answer -= count_numbers(int('1' * length), '6', '6')
            elif n_str[i] == '7':
                answer -= count_numbers(int('1' * length), '7', '7')
            elif n_str[i] == '8':
                answer -= count_numbers(int('1' * length), '8', '8')
            elif n_str[i] == '9':
                answer -= count_numbers(int('1' * length), '9', '9')

    return answer

